SELECT 
FROM TBL_PREDICTIVE_ANALYSIS
WHERE DEL_FLAG = '0' AND ANALYSIS_STATUS = 'COMPLETED'

    AND ORG_ID = #{orgId}


    AND ANALYSIS_TYPE = #{analysisType}


    LIMIT #{limit}

ORDER BY CONFIDENCE_LEVEL DESC, ACCURACY_RATE DESC, CREATE_TIME DESC

SELECT FROM TBL_PREDICTIVE_ANALYSIS WHERE MODEL_ID = #{modelId} AND DEL_FLAG = '0'
AND ORG_ID = #{orgId}
ORDER BY CREATE_TIME DESC

SELECT ANALYSIS_TYPE, AVG(ACCURACY_RATE) as avgAccuracyRate, AVG(CONFIDENCE_LEVEL) as avgConfidenceLevel, COUNT(*) as analysisCount, MAX(ACCURACY_RATE) as maxAccuracyRate, MIN(ACCURACY_RATE) as minAccuracyRate FROM TBL_PREDICTIVE_ANALYSIS WHERE DEL_FLAG = '0' AND ANALYSIS_STATUS = 'COMPLETED'
AND ORG_ID = #{orgId}
AND CREATE_TIME >= #{startDate}
AND CREATE_TIME <= #{endDate}
GROUP BY ANALYSIS_TYPE ORDER BY avgAccuracyRate DESC

SELECT FROM TBL_PREDICTIVE_ANALYSIS WHERE TARGET_PERIOD = #{targetPeriod} AND DEL_FLAG = '0' AND ANALYSIS_STATUS = 'COMPLETED'
AND ORG_ID = #{orgId}
ORDER BY CONFIDENCE_LEVEL DESC

SELECT FROM TBL_PREDICTIVE_ANALYSIS WHERE CONFIDENCE_LEVEL >= #{confidenceThreshold} AND DEL_FLAG = '0' AND ANALYSIS_STATUS = 'COMPLETED'
AND ORG_ID = #{orgId}
ORDER BY CONFIDENCE_LEVEL DESC, ACCURACY_RATE DESC

SELECT

FROM TBL_PREDICTIVE_ANALYSIS
WHERE DEL_FLAG = '0'

    AND ANALYSIS_NAME LIKE '%' || #{analysisName} || '%'


    AND PREDICTION_TYPE = #{analysisType}


    AND ANALYSIS_STATUS = #{analysisStatus}


    AND ORG_ID = #{orgId}

ORDER BY CREATE_TIME DESC
